# Helvetica-Bold differs mostly in lower case; scaled per class
_helvbold(c, w) = islowercase(c) ? round(Int, w * 1.09) : isuppercase(c) ? round(Int, w * 1.06) : w

function _helvetica()
    r = Dict{Char,Float64}(c => w for (c, w) in _HELV)
    b = Dict{Char,Float64}(c => _helvbold(c, w) for (c, w) in _HELV)
    return FontMetrics("Helvetica", r, b, r, b, 556.0)
end

